########## utils/errors/build-error-position.test.ts
import {
  describe,
  test,
  expect
} from 'vitest';
import {
  buildErrorPosition,
} from './build-error-position';

describe('buildErrorPosition', () => {
  test.each([
    [
      'root ::= "foo"',
      1,
      [
        'root ::= "foo"',
        ' ^',
      ],
    ],
    [
      'root ::= "foo"',
      5,
      [
        'root ::= "foo"',
        '     ^',
      ],
    ],
    // multi line grammars with pos on first line
    [
      'aa\\nbb',
      1,
      [
        'aa',
        ' ^',
      ],
    ],
    // multi line grammars with pos on second line, first character
    [
      'aa\\nbb',
      2,
      [
        'aa\\nbb',
        '^',
      ],
    ],
    // multi line grammars with pos on second line, second character
    [
      'aa\\nbb',
      2 + 1,
      [
        'aa\\nbb',
        ' ^',
      ],
    ],
    // multi line grammars beyond error with pos on second line
    [
      'aa\\nbb\\ncc',
      2 + 1,
      [
        'aa\\nbb',
        ' ^',
      ],
    ],
    // multi line grammars beyond error with pos on third line, first char
    [
      'aa\\nbb\\ncc',
      2 + 2 + 0,
      [
        'aa\\nbb\\ncc',
        '^',
      ],
    ],
    // multi line grammars beyond error with pos on third line, second char
    [
      'aa\\nbb\\ncc',
      2 + 2 + 1,
      [
        'aa\\nbb\\ncc',
        ' ^',
      ],
    ],
    // multi line grammars beyond error with pos on fourth line, first char
    [
      'aa\\nbb\\ncc\\ndd',
      2 + 2 + 2 + 0,
      [
        'bb\\ncc\\ndd',
        '^',
      ],
    ],
    // multi line grammars beyond error with pos on fifth line, second char
    [
      'aa\\nbb\\ncc\\ndd\\nee',
      2 + 2 + 2 + 2 + 1,
      [
        'cc\\ndd\\nee',
        ' ^',
      ],
    ],
  ])('it correctly shows position for %s', (grammar, pos, [grammarOut, posOut,]) => {
    const result = buildErrorPosition(grammar.split('\\n').join('\n'), pos);
    expect(result).toEqual([
      ...grammarOut.split('\\n'),
      posOut,
    ]);
  });

  test('it renders a message for empty input', () => {
    const result = buildErrorPosition('', 0);
    expect(result).toEqual(["No input provided"]);
  });
});
########## utils/errors/build-error-position.ts
export const MAXIMUM_NUMBER_OF_ERROR_LINES_TO_SHOW = 3;

export const buildErrorPosition = (src: string, pos: number): string[] => {
  if (src === "") {
    return ["No input provided",];
  }

  const lines = src.split('\n');

  let lineIdx = 0;
  while (lines[lineIdx] && pos > lines[lineIdx].length - 1) {
    pos -= lines[lineIdx].length;
    lineIdx += 1;
  }

  const linesToShow: string[] = [];
  for (let i = Math.max(0, lineIdx - (MAXIMUM_NUMBER_OF_ERROR_LINES_TO_SHOW - 1)); i <= lineIdx; i++) {
    linesToShow.push(lines[i]);
  }
  return [
    ...linesToShow,
    ' '.repeat(pos) + '^',
  ];
};
########## utils/errors/get-input-as-string.test.ts
import { describe, test, expect } from 'vitest';
import { getInputAsString } from './get-input-as-string';

describe('getInputAsString', () => {
  test.each([
    ['hello', 'hello'],
    [[104, 101, 108, 108, 111], 'hello'],
    [104, 'h'],
    [0x1F600, '😀'],
    [[0x1F600, 0x1F601], '😀😁'],
  ])('it correctly converts %s to string', (input, expected) => {
    const result = getInputAsString(input);
    expect(result).toEqual(expected);
  });
});
########## utils/errors/get-input-as-string.ts
import type {
  ValidInput,
} from "../../grammar-graph/types.js";

export const getInputAsString = (src: ValidInput) => {
  if (typeof src === 'string') {
    return src;
  }
  const codePoints = Array.isArray(src) ? src : [src,];
  return codePoints.map(cp => String.fromCodePoint(cp)).join('');
};
