import ast, pathlib
for p in sorted(pathlib.Path('gbnf').rglob('*.py')):
    src = p.read_text()
    tree = ast.parse(src)
    imported = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for a in node.names:
                imported.append((a.asname or a.name).split('.')[0])
    body = '\n'.join(l for l in src.splitlines() if not l.strip().startswith(('import ','from ')) and not l.strip().endswith(','))
    unused = [n for n in imported if n != 'annotations' and n not in body and '__all__' not in src]
    if unused:
        print(p, unused)
